    await expect(pg_vic.getByTestId("header-overdue-total")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("my-due-total")).toHaveText("1.00");
    await expect(pg_vic.getByTestId("my-overdue-total")).toHaveText("0.00");
    await expect(pg_vic.getByTestId("my-crew-due-total")).toHaveText("5.00");
    await expect(pg_vic.getByTestId("crew-row-Red").getByTestId("crew-lead")).toHaveText("vic");
    await expect(pg_vic.getByTestId("crew-row-Red").getByTestId("crew-due-total")).toHaveText("5.00");
