test("crew lead total scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "grace-days", "3");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-01");
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
  await ui.setSetting(pg_uma, "alert-threshold", "3.00");
  await ui.setSetting(pg_uma, "review-threshold", "4.00");
  await ui.setSetting(pg_uma, "escalate-after", "7");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "contact": " Ada@x "}));
  expect(await ui.addCrew(pg_uma, "C1", "Ada")).toBe(true);
  const pl_ada_1 = ui.must(await ui.addPlan(pg_uma, p_ada, {"amount": "3.33", "start": "2026-03-01", "end": "2026-04-30", "every": "10"}));
  expect(await ui.retire(pg_uma, p_ben, "2026-03-15")).toBe(true);
  await ui.showRetired(pg_uma, true);
  expect(await ui.retire(pg_uma, p_ada, "2026-03-09")).toBe(true);
  expect(await ui.addPatron(pg_uma, p_ben, "Ada")).toBe(true);
  expect(await ui.statement(pg_uma, p_ada)).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.pasteClaims(pg_wes, "Ada,3.33,2026-03-20,paste\nAda,0.40,,a, b")).toBeNull();
  const c_ada_1 = ui.must(await ui.addClaim(pg_wes, p_ada, {"amount": "7.77", "date": "2026-03-09", "note": "n", "tags": "a"}));
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  await ui.showRetired(pg_vic, true);
  expect(await ui.bulkSettle(pg_vic, [c_ben_0, c_ben_1, c_ben_2])).toEqual({ settled: 3, refused: 0 });
  expect(await ui.addClaim(pg_vic, p_ada, {"amount": "10.35", "date": "2026-02-10", "note": "n", "tags": "a, B"})).toBeNull();
  expect(await ui.pasteClaims(pg_vic, "Ben,0.04,2026-02-10,\nAda,0.40,2026-03-20,paste\nAda,1.00,2026-03-05,a, b")).toBeNull();

